// 1. Extract request payload
const raw = $input.first().json;
const headers = raw.headers || {};
const body = raw.body || raw;

if (!body || typeof body !== 'object') {
  return [{
    json: {
      isValid: false,
      statusCode: 400,
      errorCode: 'INVALID_REQUEST_BODY',
      errorMessage: 'Request body must be a valid JSON object.',
      requestId: null,
      data: null
    }
  }];
}

// 2. Resolve Gemini API Key (Priority: Header x-goog-api-key -> Body geminiApiKey -> Default working key)
const defaultApiKey = 'YOUR_GEMINI_API_KEY';
let apiKey = headers['x-goog-api-key'] || body.geminiApiKey || defaultApiKey;

const requestId = body.requestId || 'req_' + Date.now();
const source = (body.source || 'text').toLowerCase();
const actionHint = (body.actionHint || 'auto').toLowerCase();
const message = (body.message || '').trim();
let imageBase64 = body.imageBase64 || null;
let mimeType = body.mimeType || null;
const conversationHistory = Array.isArray(body.conversationHistory) ? body.conversationHistory : [];
const inventoryContext = Array.isArray(body.inventoryContext) ? body.inventoryContext : [];
const userPreferences = (body.userPreferences && typeof body.userPreferences === 'object') ? body.userPreferences : {};
const todayNutrition = (body.todayNutrition && typeof body.todayNutrition === 'object') ? body.todayNutrition : {};
const locale = body.locale || 'en-IN';
const modelName = body.model || 'gemini-flash-lite-latest';

// Validate supported source
const validSources = ['text', 'image', 'text_image'];
if (!validSources.includes(source)) {
  return [{
    json: {
      isValid: false,
      statusCode: 400,
      errorCode: 'INVALID_SOURCE',
      errorMessage: 'Invalid source. Supported values: text, image, text_image.',
      requestId: requestId,
      data: null
    }
  }];
}

// Validate supported actionHint
const validHints = ['auto', 'add_food_single', 'add_food_multiple', 'receipt_scan', 'log_meal', 'assistant'];
if (!validHints.includes(actionHint)) {
  return [{
    json: {
      isValid: false,
      statusCode: 400,
      errorCode: 'INVALID_ACTION_HINT',
      errorMessage: 'Invalid actionHint. Supported values: auto, add_food_single, add_food_multiple, receipt_scan, log_meal, assistant.',
      requestId: requestId,
      data: null
    }
  }];
}

// Check if image is provided when source requires it
if ((source === 'image' || source === 'text_image') && !imageBase64) {
  return [{
    json: {
      isValid: false,
      statusCode: 400,
      errorCode: 'MISSING_IMAGE',
      errorMessage: 'imageBase64 is required when source is image or text_image.',
      requestId: requestId,
      data: null
    }
  }];
}

// Check if message is provided when source is text
if (source === 'text' && !message) {
  return [{
    json: {
      isValid: false,
      statusCode: 400,
      errorCode: 'EMPTY_TEXT_MESSAGE',
      errorMessage: 'Text message cannot be empty when source is text.',
      requestId: requestId,
      data: null
    }
  }];
}

// Process and clean base64 image if provided
if (imageBase64) {
  const dataUrlMatch = imageBase64.match(/^data:([^;]+);base64,(.+)$/);
  if (dataUrlMatch) {
    if (!mimeType) mimeType = dataUrlMatch[1].toLowerCase();
    imageBase64 = dataUrlMatch[2];
  }

  mimeType = (mimeType || 'image/jpeg').toLowerCase().trim();
  const supportedMimes = ['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif'];
  if (!supportedMimes.includes(mimeType)) {
    return [{
      json: {
        isValid: false,
        statusCode: 400,
        errorCode: 'UNSUPPORTED_MIME_TYPE',
        errorMessage: 'Unsupported image MIME type: ' + mimeType + '. Supported: JPEG, PNG, WebP, HEIC.',
        requestId: requestId,
        data: null
      }
    }];
  }

  if (imageBase64.length > 10 * 1024 * 1024) {
    return [{
      json: {
        isValid: false,
        statusCode: 413,
        errorCode: 'PAYLOAD_TOO_LARGE',
        errorMessage: 'Image size exceeds maximum allowed threshold (approx 7.5 MB raw image). Please compress before uploading.',
        requestId: requestId,
        data: null
      }
    }];
  }

  const base64Clean = imageBase64.replace(/\s/g, '');
  if (!/^[A-Za-z0-9+/=]+$/.test(base64Clean)) {
    return [{
      json: {
        isValid: false,
        statusCode: 400,
        errorCode: 'INVALID_BASE64',
        errorMessage: 'The provided imageBase64 contains invalid characters.',
        requestId: requestId,
        data: null
      }
    }];
  }
  imageBase64 = base64Clean;
}

return [{
  json: {
    isValid: true,
    statusCode: 200,
    requestId: requestId,
    geminiApiKey: apiKey,
    modelName: modelName,
    source: source,
    actionHint: actionHint,
    message: message,
    imageBase64: imageBase64,
    mimeType: mimeType,
    conversationHistory: conversationHistory,
    inventoryContext: inventoryContext,
    userPreferences: userPreferences,
    todayNutrition: todayNutrition,
    locale: locale
  }
}];

