const item = $input.first().json;
const parts = [];

// Attach image as inlineData part if provided
if (item.imageBase64 && item.mimeType) {
  parts.push({
    inlineData: {
      mimeType: item.mimeType,
      data: item.imageBase64
    }
  });
}

// Build contextual prompt text
let promptText = 'USER INSTRUCTION / MESSAGE: ' + (item.message || '(Image uploaded without text message)') + '

';
promptText += 'OPERATION HINT: ' + item.actionHint + '
';
promptText += 'LOCALE: ' + item.locale + '

';

if (item.conversationHistory && item.conversationHistory.length > 0) {
  promptText += 'RECENT CONVERSATION HISTORY (Supplied by client):
';
  const recent = item.conversationHistory.slice(-5);
  for (const c of recent) {
    promptText += '- [' + (c.role || 'user') + ']: ' + (c.message || c.text || '') + '
';
  }
  promptText += '
';
}

if (item.inventoryContext && item.inventoryContext.length > 0) {
  promptText += 'CURRENT FRIDGE INVENTORY CONTEXT (Supplied by client):
';
  for (const inv of item.inventoryContext) {
    promptText += '- ID: ' + (inv.id || 'N/A') + ' | ' + (inv.name || 'Unknown') + ' | Qty: ' + (inv.quantity || 'N/A') + ' | Category: ' + (inv.category || 'N/A') + ' | ExpiryDays: ' + (inv.expiryDays ?? 'N/A') + '
';
  }
  promptText += '
';
} else {
  promptText += 'CURRENT FRIDGE INVENTORY CONTEXT: (None provided by client)

';
}

if (item.userPreferences && Object.keys(item.userPreferences).length > 0) {
  promptText += 'USER PREFERENCES: ' + JSON.stringify(item.userPreferences) + '

';
}

if (item.todayNutrition && Object.keys(item.todayNutrition).length > 0) {
  promptText += 'TODAY NUTRITION TOTALS: ' + JSON.stringify(item.todayNutrition) + '

';
}

promptText += 'Please analyze the request and provide the JSON output strictly following the schema and category mapping rules.';

parts.push({
  text: promptText
});

const geminiPayload = {
  contents: [
    {
      role: 'user',
      parts: parts
    }
  ],
  systemInstruction: {
    parts: [
      {
        text: "You are the NutriFridge AI Food & Nutrition Assistant for the NutriFridge mobile application.
Your goal is to parse natural-language food text, grocery items, meal descriptions, receipts, and food photos into structured, reliable JSON for the Flutter client.

CORE RULES:
1. DISTINGUISH INVENTORY ADDITION FROM MEAL LOGGING:
   - Purchasing, stocking, or having food ("Add 2 apples to fridge", "Bought milk and paneer", "Stock 6 eggs") -> action: "add_inventory_items".
   - Consuming food ("I ate a paneer rice bowl", "Had 2 chapatis and dal", "Finished a bowl of curd for lunch") -> action: "log_meal".
   - Do NOT confuse food the user owns with food the user has eaten.
   - If an attached photo or text is ambiguous, return action: "clarification_needed" with a polite clarifyingQuestion.

2. CATEGORY MAPPING (EXACTLY 11 ALLOWED CATEGORIES):
   Every item in "inventoryItems" MUST use one of these EXACT 11 categories:
   - "Dairy Products" (milk, cheese, paneer, curd, yogurt, butter)
   - "Vegetables" (tomato, carrot, broccoli, capsicum, spinach, potato, onion)
   - "Fruits" (apple, banana, orange, grapes, mango, berries)
   - "Non-Veg" (eggs, chicken, fish, mutton, seafood)
   - "Meals & Leftovers" (dal rice, pasta, curry, prepared dishes)
   - "Packaged Food" (bread, peanut butter, jam, biscuits, noodles)
   - "Drinks & Juices" (juice, soda, iced tea, coconut water)
   - "Ice Cream" (ice cream tubs, popsicles)
   - "Frozen Food" (frozen peas, frozen corn, fries, nuggets)
   - "Dry Fruits" (almonds, cashews, raisins, walnuts, nuts mix)
   - "Others" (honey, chocolate, spices, condiments, miscellaneous)
   Never invent new categories. Normalize synonyms into one of these 11.

3. QUANTITIES AND UNITS:
   - Return numeric "quantity" (positive number) and standard "unit" ("pieces", "g", "kg", "ml", "L", "pack", "bottle", "jar", "tub", "box").
   - If quantity cannot be inferred with confidence, set quantity: null and unit: null.

4. MEAL LOGGING & NUTRITION:
   - For "log_meal", return a "meal" object with name, mealType ("breakfast", "lunch", "dinner", "snack"), estimated nutrition (calories, proteinG, carbsG, fatG), and ingredients list.
   - All nutritional numbers MUST be flagged as approximate estimates (isEstimate: true).
   - If an ingredient matches an existing item in the supplied "inventoryContext", provide its exact "matchedInventoryItemId". NEVER invent inventory IDs.
   - Set "deductionNeedsUserConfirmation: true" on all ingredients. Never auto-deduct without user confirmation.

5. INVENTORY QUERIES:
   - When answering questions about existing stock ("What fruit do I have?", "How much milk is left?"), use ONLY the items in "inventoryContext".
   - If "inventoryContext" is empty or missing, explicitly state that current fridge inventory was not provided. Never invent inventory items.

6. CONFIRMATION & CLARIFICATION:
   - Any mutation action ("add_inventory_items", "log_meal", "update_inventory_item", "remove_inventory_item") MUST have "requiresConfirmation": true.
   - If request is ambiguous, unreadable receipt, or missing critical data, set action: "clarification_needed", needsClarification: true, and provide a clarifyingQuestion.

OUTPUT JSON SCHEMA:
You MUST output ONLY a valid JSON object matching this exact schema:
{
  "action": "add_inventory_items" | "log_meal" | "query_inventory" | "assistant_reply" | "update_inventory_item" | "remove_inventory_item" | "clarification_needed",
  "assistantMessage": "Human-friendly concise response to the user",
  "requiresConfirmation": boolean,
  "needsClarification": boolean,
  "clarifyingQuestion": string | null,
  "inventoryItems": [
    {
      "name": "string",
      "category": "Dairy Products" | "Others" | "Non-Veg" | "Meals & Leftovers" | "Packaged Food" | "Drinks & Juices" | "Vegetables" | "Fruits" | "Ice Cream" | "Frozen Food" | "Dry Fruits",
      "quantity": number | null,
      "unit": "pieces" | "g" | "kg" | "ml" | "L" | "pack" | "bottle" | "jar" | "tub" | "box" | null,
      "expiryDate": "YYYY-MM-DD" | null,
      "expiryDaysEstimate": number | null,
      "confidence": number
    }
  ],
  "meal": {
    "name": "string",
    "mealType": "breakfast" | "lunch" | "dinner" | "snack",
    "ingredients": [
      {
        "name": "string",
        "quantity": number | null,
        "unit": "g" | "ml" | "pieces" | null,
        "matchedInventoryItemId": "string" | null,
        "suggestedDeductionQuantity": number | null,
        "deductionNeedsUserConfirmation": true
      }
    ],
    "nutrition": {
      "calories": number,
      "proteinG": number,
      "carbsG": number,
      "fatG": number,
      "isEstimate": true,
      "estimateNote": "Approximate estimate"
    }
  } | null,
  "inventoryQueryResults": [
    {
      "name": "string",
      "quantity": "string",
      "category": "string",
      "status": "string"
    }
  ],
  "suggestedInventoryDeductions": [],
  "warnings": ["string"]
}"
      }
    ]
  },
  generationConfig: {
    temperature: 0.2,
    maxOutputTokens: 2048,
    responseMimeType: 'application/json'
  }
};

const targetModel = item.modelName || 'gemini-flash-lite-latest';
const apiUrl = 'https://generativelanguage.googleapis.com/v1beta/models/' + targetModel + ':generateContent';

return [{
  json: {
    requestId: item.requestId,
    geminiApiKey: item.geminiApiKey,
    apiUrl: apiUrl,
    geminiPayload: geminiPayload
  }
}];

const inputItem = $input.first().json;
const originalRequestId = $('Validate and Normalize Request').first().json.requestId || 'req_unknown';

// Check if HTTP Request returned an upstream error
if (inputItem.error || inputItem.statusCode >= 400) {
  const status = inputItem.statusCode || (inputItem.error ? 502 : 500);
  let userFriendlyMsg = 'NutriFridge could not complete AI analysis right now.';

  if (status === 401 || status === 403) {
    userFriendlyMsg = 'Google Gemini API authentication failed. Please configure a valid API key in n8n (x-goog-api-key).';
  } else if (status === 429) {
    userFriendlyMsg = 'Google Gemini API quota or rate limit exceeded. Please try again in a few moments.';
  }

  return [{
    json: {
      ok: false,
      httpStatus: status === 401 || status === 403 ? 502 : status,
      responseBody: {
        ok: false,
        requestId: originalRequestId,
        error: {
          code: 'GEMINI_UPSTREAM_ERROR',
          message: userFriendlyMsg,
          retryable: status >= 500 || status === 429
        }
      }
    }
  }];
}

// Extract candidates from Gemini response
const candidates = inputItem.candidates;
if (!candidates || !Array.isArray(candidates) || candidates.length === 0) {
  return [{
    json: {
      ok: false,
      httpStatus: 502,
      responseBody: {
        ok: false,
        requestId: originalRequestId,
        error: {
          code: 'EMPTY_AI_CANDIDATE',
          message: 'The AI model returned no content candidates.',
          retryable: true
        }
      }
    }
  }];
}

const firstCandidate = candidates[0];
if (!firstCandidate.content || !firstCandidate.content.parts || !Array.isArray(firstCandidate.content.parts)) {
  return [{
    json: {
      ok: false,
      httpStatus: 502,
      responseBody: {
        ok: false,
        requestId: originalRequestId,
        error: {
          code: 'MALFORMED_AI_PARTS',
          message: 'The AI response structure was missing content parts.',
          retryable: true
        }
      }
    }
  }];
}

let combinedText = '';
for (const part of firstCandidate.content.parts) {
  if (part.text) {
    combinedText += part.text;
  }
}

combinedText = combinedText.trim();
if (combinedText.startsWith('```')) {
  combinedText = combinedText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(combinedText);
} catch (e) {
  return [{
    json: {
      ok: false,
      httpStatus: 502,
      responseBody: {
        ok: false,
        requestId: originalRequestId,
        error: {
          code: 'INVALID_AI_JSON',
          message: 'The AI model generated non-parseable JSON content.',
          retryable: true
        }
      }
    }
  }];
}

if (!parsed || typeof parsed !== 'object') {
  return [{
    json: {
      ok: false,
      httpStatus: 502,
      responseBody: {
        ok: false,
        requestId: originalRequestId,
        error: {
          code: 'INVALID_AI_SCHEMA',
          message: 'The AI model did not return a valid JSON object.',
          retryable: true
        }
      }
    }
  }];
}

const CANONICAL_CATEGORIES = [
  'Dairy Products',
  'Others',
  'Non-Veg',
  'Meals & Leftovers',
  'Packaged Food',
  'Drinks & Juices',
  'Vegetables',
  'Fruits',
  'Ice Cream',
  'Frozen Food',
  'Dry Fruits'
];

function normalizeCategory(cat) {
  if (!cat || typeof cat !== 'string') return 'Others';
  const clean = cat.trim();
  for (const c of CANONICAL_CATEGORIES) {
    if (c.toLowerCase() === clean.toLowerCase()) return c;
  }
  const u = clean.toUpperCase();
  if (u.includes('DAIRY')) return 'Dairy Products';
  if (u.includes('ICE CREAM')) return 'Ice Cream';
  if (u.includes('FROZEN')) return 'Frozen Food';
  if (u.includes('DRY FRUIT')) return 'Dry Fruits';
  if (u.includes('NON-VEG') || u.includes('NON VEG')) return 'Non-Veg';
  if (u.includes('LEFTOVER') || u.includes('MEAL')) return 'Meals & Leftovers';
  if (u.includes('PACKAGE')) return 'Packaged Food';
  if (u.includes('DRINK') || u.includes('JUICE')) return 'Drinks & Juices';
  if (u.includes('VEG')) return 'Vegetables';
  if (u.includes('FRUIT')) return 'Fruits';
  return 'Others';
}

const validActions = [
  'add_inventory_items',
  'log_meal',
  'query_inventory',
  'assistant_reply',
  'update_inventory_item',
  'remove_inventory_item',
  'clarification_needed'
];

let action = (parsed.action || 'assistant_reply').toLowerCase();
if (!validActions.includes(action)) {
  action = 'assistant_reply';
}

const assistantMessage = (typeof parsed.assistantMessage === 'string' && parsed.assistantMessage.trim().length > 0)
  ? parsed.assistantMessage.trim()
  : 'Processed your request successfully.';

const needsClarification = action === 'clarification_needed' || Boolean(parsed.needsClarification);
const clarifyingQuestion = needsClarification ? (parsed.clarifyingQuestion || parsed.assistantMessage || 'Could you please clarify your request?') : null;

const mutationActions = ['add_inventory_items', 'log_meal', 'update_inventory_item', 'remove_inventory_item'];
const requiresConfirmation = mutationActions.includes(action) ? true : Boolean(parsed.requiresConfirmation);

let inventoryItems = [];
if (Array.isArray(parsed.inventoryItems)) {
  for (const it of parsed.inventoryItems) {
    if (it && typeof it === 'object' && it.name) {
      const q = typeof it.quantity === 'number' && it.quantity > 0 ? it.quantity : null;
      inventoryItems.push({
        name: String(it.name).trim(),
        category: normalizeCategory(it.category),
        quantity: q,
        unit: it.unit ? String(it.unit).trim() : (q ? 'pieces' : null),
        expiryDate: it.expiryDate || null,
        expiryDaysEstimate: typeof it.expiryDaysEstimate === 'number' ? it.expiryDaysEstimate : null,
        confidence: typeof it.confidence === 'number' ? Math.min(1.0, Math.max(0.0, it.confidence)) : 0.95
      });
    }
  }
}

let meal = null;
if (action === 'log_meal' && parsed.meal && typeof parsed.meal === 'object') {
  const m = parsed.meal;
  const ingredients = [];
  if (Array.isArray(m.ingredients)) {
    for (const ing of m.ingredients) {
      if (ing && typeof ing === 'object' && ing.name) {
        ingredients.push({
          name: String(ing.name).trim(),
          quantity: typeof ing.quantity === 'number' ? ing.quantity : null,
          unit: ing.unit ? String(ing.unit).trim() : null,
          matchedInventoryItemId: ing.matchedInventoryItemId || null,
          suggestedDeductionQuantity: typeof ing.suggestedDeductionQuantity === 'number' ? ing.suggestedDeductionQuantity : null,
          deductionNeedsUserConfirmation: true
        });
      }
    }
  }

  const rawNutr = m.nutrition || {};
  meal = {
    name: m.name ? String(m.name).trim() : 'Logged Meal',
    mealType: m.mealType ? String(m.mealType).toLowerCase().trim() : 'lunch',
    ingredients: ingredients,
    nutrition: {
      calories: typeof rawNutr.calories === 'number' ? Math.round(rawNutr.calories) : 450,
      proteinG: typeof rawNutr.proteinG === 'number' ? Math.round(rawNutr.proteinG) : 20,
      carbsG: typeof rawNutr.carbsG === 'number' ? Math.round(rawNutr.carbsG) : 50,
      fatG: typeof rawNutr.fatG === 'number' ? Math.round(rawNutr.fatG) : 15,
      isEstimate: true,
      estimateNote: rawNutr.estimateNote || 'Nutrition and portion values are approximate estimates.'
    }
  };
}

const inventoryQueryResults = Array.isArray(parsed.inventoryQueryResults) ? parsed.inventoryQueryResults : [];
const suggestedInventoryDeductions = Array.isArray(parsed.suggestedInventoryDeductions) ? parsed.suggestedInventoryDeductions : [];
const warnings = Array.isArray(parsed.warnings) ? parsed.warnings : [];

const finalNormalizedResponse = {
  ok: true,
  requestId: originalRequestId,
  action: action,
  assistantMessage: assistantMessage,
  requiresConfirmation: requiresConfirmation,
  needsClarification: needsClarification,
  clarifyingQuestion: clarifyingQuestion,
  inventoryItems: inventoryItems,
  meal: meal,
  inventoryQueryResults: inventoryQueryResults,
  suggestedInventoryDeductions: suggestedInventoryDeductions,
  warnings: warnings
};

return [{
  json: {
    ok: true,
    httpStatus: 200,
    responseBody: finalNormalizedResponse
  }
}];
